def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Sort the classes by their number of ancestors
    sorted_classes = sorted(classes, key=lambda cls: len(inspect.getmro(cls)))

    # Initialize the minimum set of bases to the first class in the sorted list
    min_bases = {sorted_classes[0]}

    # Iterate over the remaining classes in the sorted list
    for cls in sorted_classes[1:]:
        # If the current class is not a subclass of any of the classes in the minimum set, add it to the minimum set
        if not any(issubclass(cls, base) for base in min_bases):
            min_bases.add(cls)

    # Return the minimum set of bases
    return list(min_bases)

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Sort the list of classes based on the number of ancestors they have
    sorted_classes = sorted(classes, key=lambda cls: len(cls.mro()))

    # Initialize the minimum set of bases
    min_bases = set()

    # Iterate over the sorted list of classes
    for cls in sorted_classes:
        # If the class is not in the minimum set of bases, add it
        if cls not in min_bases:
            min_bases.add(cls)

        # If the class has a base that is already in the minimum set of bases, remove it
        for base in cls.__bases__:
            if base in min_bases:
                min_bases.remove(cls)
                break

    # Return the minimum set of bases
    return list(min_bases)

