def normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """

    # Flatten the sequence of arguments
    flat_sequence = []
    for arg in sequence:
        if isinstance(arg, (list, tuple)):
            flat_sequence += arg
        else:
            flat_sequence.append(arg)

    # Remove any duplicates
    flat_sequence = list(set(flat_sequence))

    # Check if output is None
    if output is None:
        # If output is None, default to a list
        output = []

    # Iterate over the flattened sequence and expand
    # any Declarions or tuples
    for arg in flat_sequence:
        if isinstance(arg, Declaration):
            output.extend(arg.interfaces)
        elif isinstance(arg, (list, tuple)):
            output.extend(arg)
        else:
            output.append(arg)

    return output

