    if level == 0:
        return d1
    diff = {}
    for k, v in d1.items():
        if k not in d2 or (level < 0 and isinstance(v, dict) and level != 0):
            diff[k] = v
        elif isinstance(v, dict):
            diff[k] = difference(v, d2[k], level-1)
    return diff

