def _validate_labels(labels):
    # Create a list to store the errors
    errors = []

    # Iterate through the labels
    for key, value in labels.items():
        # Check if the key is a string
        if not isinstance(key, str):
            errors.append({key: "Label key must be a string"})
            continue

        # Check if the value is a string
        if not isinstance(value, str):
            errors.append({key: "Label value must be a string"})
            continue

        # Check if the key and value match the regex
        if not re.match(r"^[a-zA-Z0-9_\\-\\.]+$", key):
            errors.append({key: "Label key does not match the regex ^[a-zA-Z0-9_\\-\\.]+$"})
        if not re.match(r"^[a-zA-Z0-9_\\-\\.]+$", value):
            errors.append({key: "Label value does not match the regex ^[a-zA-Z0-9_\\-\\.]+$"})

    # If there are any errors, raise an exception
    if errors:
        raise ValidationError(messages=errors)

