def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """
    Together with :func:``update_last_applied_manifest_list_from_resp``, this function is called recursively
    to update a partial ``last_applied_manifest`` from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response
    """
    for key, value in observer_schema.items():
        if not isinstance(value, dict):
            continue

        if key not in last_applied_manifest:
            last_applied_manifest[key] = {}
        if key not in response:
            raise KeyError(f"Observed field '{key}' not present in Kubernetes response")

        update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], value, response[key])

    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, value in observer_schema.items():
        if field not in response:
            raise KeyError(f"Observed field '{field}' not present in Kubernetes response")
        if field not in last_applied_manifest:
            last_applied_manifest[field] = value
        update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], value, response[field])

