    for field, value in observer_schema.items():
        if field not in last_applied_manifest:
            last_applied_manifest[field] = value
        elif isinstance(value, dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], value, response[field])
        else:
            last_applied_manifest[field] = response[field]
    return last_applied_manifest

def update_last_applied_manifest(last_applied_manifest, observer_schema, response):
    for field in observer_schema.get("observed_fields", []):
        field_key = field["key"]
        if field_key not in last_applied_manifest:
            last_applied_manifest[field_key] = None
    for key, value in response.items():
        if key in observer_schema.get("observed_fields", []):
            last_applied_manifest[key] = value
    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    result = {}
    for resource in app.spec.manifest:
        sub_result = {}
        sub_result["apiVersion"] = resource.apiVersion
        sub_result["kind"] = resource.kind
        sub_result["metadata"] = {"name": resource.metadata.name}
        sub_result["spec"] = resource.spec
        result[resource.kind] = sub_result
    return result

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    schema = {}
    for manifest in app.spec.manifest:
        if manifest.kind not in schema:
            schema[manifest.kind] = {"type": "object", "properties": {}}
            for prop in manifest.properties:
                schema[manifest.kind]["properties"][prop] = {"type": "string"}
    return schema

def generate_default_observer_schema(app: krake.data.kubernetes.Application) -> None:
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    for resource in app.spec.manifest:
        if not resource.observer_schema:
            resource.observer_schema = krake.data.kubernetes.ObserverSchema(
                resource.resource_name, resource.kind
            )
            app.spec.manifest[resource.resource_name] = resource

