def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    return all(digest in manifest_files for digest in digests_used)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Check if all digests in manifest are present in the digests used
    for digest in self.digests:
        if digest not in digests_used:
            return False
    # Check if all digests used are present in the manifest
    for digest in digests_used:
        if digest not in self.digests:
            return False
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    # get the digests from the manifest files
    manifest_digests = set()
    for manifest_file in manifest_files:
        manifest_digests |= get_digests_from_manifest(manifest_file)

    # check if all digests in manifest_digests are present and used in digests_used
    for digest in manifest_digests:
        if digest not in digests_used:
            return False

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    # Check if all digests in the manifest are present
    for digest in manifest_files:
        if not digest.exists():
            raise ValueError('Digest {0} is not present'.format(digest))

    # Check if all active digests are used
    for digest in digests_used:
        if digest not in manifest_files:
            raise ValueError('Digest {0} is not used'.format(digest))

def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Invalid prior object")
    if prior.inventory.meta != self.inventory.meta:
        raise ValueError("Inconsistent inventory metadata")
    prior_state = prior.inventory.state
    current_state = self.inventory.state
    if len(prior_state) > len(current_state):
        raise ValueError("Prior state is longer than current state")
    for i in range(len(prior_state)):
        if prior_state[i] != current_state[i]:
            raise ValueError("Prior state is not a prefix of the current state")
    return True

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for state in inventory:
        for file in state["files"]:
            logical_path_map[file["logical_path"]] = file["content_file"]
    return logical_path_map

