def validate_fixity(self, fixity, manifest_files):
    # Check that the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise Exception("Invalid fixity block: fixity block must be a dictionary")

    # Check that all files listed in the fixity block are also listed in the manifest
    for file in fixity:
        if file not in manifest_files:
            raise Exception("Invalid fixity block: file '{}' is not listed in the manifest".format(file))

    # Check that all files in the manifest have a corresponding fixity entry
    for file in manifest_files:
        if file not in fixity:
            raise Exception("Invalid fixity block: file '{}' does not have a fixity entry".format(file))

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Validate the structure of the fixity block
    if not isinstance(fixity, dict):
        raise TypeError("Fixity block must be a dictionary")

    # Validate that the fixity block contains only files listed in the manifest
    for file_path, checksums in fixity.items():
        if file_path not in manifest_files:
            raise ValueError(f"File {file_path} is not in the manifest")
        if not isinstance(checksums, dict):
            raise TypeError("Checksums for file {file_path} must be a dictionary")
        for algorithm, checksum in checksums.items():
            if not isinstance(algorithm, str):
                raise TypeError(f"Checksum algorithm {algorithm} for file {file_path} must be a string")
            if not isinstance(checksum, str):
                raise TypeError(f"Checksum {checksum} for file {file_path} must be a string")

def validate_fixity(self, fixity, manifest_files):
    for file in fixity:
        if file not in manifest_files:
            raise ValueError(f"File '{file}' in fixity block is not listed in the manifest.")

def validate_fixity(self, fixity, manifest_files):
    if not isinstance(fixity, list):
        raise ValueError("Fixity block must be a list")
    for item in fixity:
        if not isinstance(item, dict):
            raise ValueError("Fixity item must be a dictionary")
        if "file" not in item:
            raise ValueError("Fixity item must have a 'file' key")
        file = item["file"]
        if file not in manifest_files:
            raise ValueError(f"File '{file}' not found in manifest")
        if "fixity" not in item:
            raise ValueError("Fixity item must have a 'fixity' key")
        fixity = item["fixity"]
        if not isinstance(fixity, str):
            raise ValueError("Fixity value must be a string")
        if fixity not in ["md5", "sha1", "sha256", "sha512"]:
            raise ValueError(f"Invalid fixity algorithm '{fixity}'")
    return True

def _group_files_by_xml_filename(xmls, files):
    result = {}
    for file in files:
        basename = os.path.basename(file)
        xml_basename = os.path.splitext(basename)[0]
        if xml_basename in xmls:
            if xml_basename not in result:
                result[xml_basename] = Package(xml_basename)
            result[xml_basename].add_file(file)
    return result

def _group_files_by_xml_filename(xml_filename, files):
    result = {}
    for file in files:
        if file.endswith('.xml') and file.startswith(xml_filename):
            key = file.split('.')[0]
            if key not in result:
                result[key] = []
            result[key].append(file)
    return result

def _explore_folder(folder):
    import os
    import xml.etree.ElementTree as ET

    package_data = {}
    for file in os.listdir(folder):
        filename, file_ext = os.path.splitext(file)
        if file_ext == '.xml':
            tree = ET.parse(os.path.join(folder, file))
            basename = os.path.basename(filename)
            if basename not in package_data:
                package_data[basename] = {}
            package_data[basename].update(_parse_package_data(tree, basename))
    return package_data

def _explore_folder(folder):
    data = {}
    for path in os.listdir(folder):
        basename = os.path.splitext(os.path.basename(path))[0]
        data[basename] = []
        with open(path, 'r') as file:
            lines = file.readlines()
            for line in lines:
                if line.startswith('<'):
                    data[basename].append(line.strip())
    return data

