    if lang not in ['en', 'pt']:
        raise ValueError("Invalid language code")
    with open(file_path, 'rb') as f:
        file_content = f.read()
    renditions = {
        'original': file_content,
        lang: file_content
    }
    keys = sorted(renditions.keys())
    with open(f'artigo02-{lang}.pdf', 'wb') as f:
        for key in keys:
            f.write(renditions[key])

