def _extract_number_and_supplment_from_issue_element(issue):
    number_pattern = r"(?P<number>\d+)"
    suppl_pattern = r"(?P<suppl>Suppl\.?\s*\d*)"
    pattern = r"\s*".join([number_pattern, suppl_pattern])
    match = re.search(pattern, issue)
    if match:
        number = match.group("number")
        suppl = match.group("suppl")
        return (number, suppl)
    else:
        return None, None

def _extract_number_and_supplment_from_issue_element(issue):
    number = ''
    suppl = ''
    for char in issue:
        if char.isdigit():
            number += char
        elif char.lower() == 's':
            suppl += char
        elif char.lower() == 'p':
            suppl += char
        elif char.lower() == 'r':
            suppl += char
        elif char.lower() == 'e':
            suppl += char
        elif char.lower() == '.'):
            break
    return number, suppl.strip()

