def run_command(commands, args, cwd=None, verbose=False, hide_stder=False, env=None):
    process = subprocess.Popen(commands, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = process.communicate()
    if verbose:
        print(stdout)
    if hide_stderr:
        print(stderr, end='')
    return process.returncode

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if isinstance(commands, str):
        commands = [commands]
    if isinstance(args, str):
        args = [args]
    if cwd is not None:
        os.chdir(cwd)
    if env is not None:
        os.environ.update(env)
    stdout = ""
    stderr = ""
    for command in commands:
        proc = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        for arg in args:
            proc.stdin.write(arg.encode())
        proc.stdin.close()
        stdout += proc.stdout.read().decode()
        stderr += proc.stderr.read().decode()
    if hide_stderr:
        stderr = ""
    if verbose:
        print(f"Command: {' '.join(commands)}")
        print(f"Args: {', '.join(args)}")
        print(f"CWD: {cwd or '.'}")
        print(f"Environment: {env or ''}")
        print(f"stdout: {stdout}")
        print(f"stderr: {stderr}")
    return stdout, stderr

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if cwd is not None:
        os.chdir(cwd)
    if env is not None:
        for key, value in env.items():
            os.environ[key] = value
    combined_command = " ".join(commands)
    if args:
        combined_command += " " + " ".join(args)
    if verbose:
        print(f"Running command: {combined_command}")
    try:
        result = subprocess.run(combined_command, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if hide_stderr:
            result.stderr = b""
        return result.stdout.decode("utf-8").strip()
    except subprocess.CalledProcessError as e:
        if hide_stderr:
            e.stderr = b""
        raise e
    finally:
        if cwd is not None:
            os.chdir(old_cwd)
        if env is not None:
            for key in env.keys():
                del os.environ[key]

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not commands:
        return

    if not isinstance(commands, list):
        commands = [commands]

    if cwd is None:
        cwd = os.getcwd()

    for command in commands:
        try:
            subprocess.check_call(command, cwd=cwd, shell=True)
