def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.startswith('v'):
        version = version[1:]
    parts = version.split('.')
    for i in range(len(parts)-1, -1, -1):
        if parts[i].isdigit():
            parts[i] = str(int(parts[i]) + 1)
            break
    return 'v' + '.'.join(parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        prefix, number = version.split('.')
        return f"{prefix}.{int(number) + 1}"
    except ValueError:
        return f"{version}.1"

def next_version(version):
    if version.startswith("0"):
        return version.replace("0", "1")
    else:
        return str(int(version) + 1)

def next_version(version):
    # Calculate the next version by incrementing the last digit of the version string
    version_list = list(version)
    last_digit = version_list[-1]
    if last_digit == '9':
        version_list[-2] = str(int(version_list[-2]) + 1)
        version_list[-1] = '0'
    else:
        version_list[-1] = str(int(last_digit) + 1)
    return ''.join(version_list)

def validate_version_inventories(version_dirs):
    root_inventory = None
    for version_dir in version_dirs:
        inventory_file = f"{version_dir}/inventory.json"
        if not os.path.exists(inventory_file):
            return False
        with open(inventory_file, "r") as f:
            inventory = json.load(f)
        if not root_inventory:
            root_inventory = inventory
        else:
            for fname in inventory:
                if fname not in root_inventory:
                    return False
                if inventory[fname] != root_inventory[fname]:
                    return False
    return True

def find_path_type(path):
    """Return a string indicating the type of thing at the given path."""
    namaste_files = [f for f in os.listdir(path) if re.match(r'^0-\*', f)]
    if len(namaste_files) == 0:
        return 'file'
    if len(namaste_files) > 1:
        return 'unable to determine'
    namaste_file = namaste_files[0]
    if re.match(r'^ocfl_object_', namaste_file):
        return 'object'
    if re.match(r'^ocfl_root_', namaste_file):
        return 'root'
    return 'file'

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        namastes = glob.glob(os.path.join(path, '0=*'))
        if len(namastes) == 1:
            return 'root'
        elif len(namastes) == 2:
            return 'object'
        else:
            return 'file'
    except (IOError, OSError) as e:
        return str(e)

