def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None and padding > 0:
        number = number % (10 ** padding)
    output = ""
    for i in range(len(alphabet)):
        if number >= (10 ** i):
            output += alphabet[(number // (10 ** i)) % 10]
    return output

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if padding is not None and padding < 0:
        raise ValueError("padding must be non-negative")

    if not alphabet:
        raise ValueError("alphabet must not be empty")

    result = ""
    current = abs(number)
    base = len(alphabet)

    while current > 0:
        result = alphabet[current % base] + result
        current //= base

    if number < 0:
        result = "-" + result

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None:
        return ''.join(alphabet[(number >> i) & 1] for i in range(padding-1, -1, -1))
    else:
        return ''.join(alphabet[(number >> i) & 1] for i in range(8*len(alphabet)-1, -1, -1))

