def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    try:
        archive_extension = archive_path.split(".")[-1]
        tmp_dir = Path(tmp_path) / "tmp_repo"
        if not tmp_dir.exists():
            tmp_dir.mkdir(parents=True)
        if filename:
            archive_filename = filename
        else:
            archive_filename = archive_path.split("/")[-1].split(".")[0]
        tmp_file = tmp_dir / filename
        with open(tmp_file, "wb") as f:
            subprocess.check_output(["cp", archive_path, tmp_file])
        subprocess.check_output(["unarchive", archive_extension], cwd=tmp_dir)
        subprocess.check_output(["tar", "-xvf", archive_filename], cwd=tmp_dir)
        return str(tmp_file.absolute())
    except subprocess.CalledProcessError as e:
        raise Exception("Unable to prepare repository from archive")

