def is_local(host):
    try:
        # Try to resolve the hostname
        hostname, _, _ = socket.gethostbyname(host)
    except socket.gaierror:
        # If the hostname could not be resolved, assume it is not local
        return False

    # Check if the resolved hostname is equal to localhost
    if hostname == "localhost":
        return True

    # Check if the resolved hostname is equal to the ipv4 loopback address
    if hostname == "127.0.0.1":
        return True

    # Check if the resolved hostname is equal to the ipv6 loopback address
    if hostname == "::1":
        return True

    # If none of the above conditions are met, assume the host is not local
    return False

