def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    # Check if the file already exists and has a different mode
    if os.path.exists(config_filename):
        existing_mode = oct(os.stat(config_filename).st_mode & 0o777)
        if existing_mode != mode:
            raise Exception(f"File {config_filename} already exists with different permissions")

    # If the file doesn't exist or the overwrite flag is set, create the directory and write the config
    if not os.path.exists(config_filename) or overwrite:
        try:
            os.makedirs(os.path.dirname(config_filename), exist_ok=True)
            with open(config_filename, "w") as f:
                f.write(rendered_config)
        except Exception as e:
            raise Exception(f"Failed to write configuration file {config_filename}: {e}")

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    env_var = os.getenv(matcher.group(1))
    if env_var is None:
        if matcher.group(2) is None:
            raise Error("Missing value for environment variable '%s'" % matcher.group(1))
        else:
            return matcher.group(2)
    else:
        return env_var

def _resolve_string(matcher):
    if not matcher or not hasattr(matcher, 'group'):
        raise ValueError('Invalid matcher')

    name = matcher.group('name')
    default = matcher.group('default')

    try:
        return os.environ[name]
    except KeyError:
        if default is not None:
            return default
        else:
            raise Error('Value for variable %s is not defined and no default value provided' % name)

def _resolve_string(matcher: str) -> str:
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    name, _, default = matcher.partition('=')
    value = os.environ.get(name)
    if value is None:
        if default is None:
            raise Error(f'Environment variable {name} is not defined')
        else:
            value = default
    return value

def _resolve_string(matcher):
    variable_name = matcher.group(1)
    default_value = matcher.group(2)
    if variable_name in os.environ:
        return os.environ[variable_name]
    elif default_value:
        return default_value
    else:
        raise Error(f"Variable {variable_name} is not defined in environment and no default value is provided.")

