        return {p: cls.protocol_handlers(p) for p in cls.supported_protocol_versions}
    if type(protocol_version) is not tuple:
        raise TypeError("Protocol version must be passed as a tuple")
    if protocol_version in cls.supported_protocol_versions:
        return {protocol_version: _get_protocol_handler(protocol_version)}
    else:
