def _get_seq_with_type(seq, bufsize=None):
    """
    Returns a (sequence, type) pair where the sequence is derived from the given sequence
    or is the given sequence itself if it is of a sequence type.

    Args:
        seq: The sequence to derive the output from.
        bufsize: The buffer size to use when creating the sequence.

    Returns:
        A (sequence, type) pair.
    """
    if isinstance(seq, type(str)):
        return seq, type(seq)
    else:
        return list(seq), type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, str):
        return [seq], str
    elif isinstance(seq, bytes):
        return [seq], bytes
    elif isinstance(seq, memoryview):
        return [seq], memoryview
    elif isinstance(seq, range):
        return [seq], range
    elif isinstance(seq, slice):
        return [seq], slice
    elif isinstance(seq, tuple):
        return [seq], tuple
    elif isinstance(seq, list):
        return [seq], list
    elif isinstance(seq, collections.abc.MutableSequence):
        return [seq], collections.abc.MutableSequence
    elif isinstance(seq, collections.abc.Sequence):
        return [seq], collections.abc.Sequence
    else:
        raise TypeError("Invalid sequence type: {}".format(type(seq).__name__))

