def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):

    if make_value is None:
        make_value = lambda bin_: bin_.content

    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError("get_coordinate must be 'left', 'right', "
                         "'middle' or None")

    if scale is not None and not isinstance(scale, HistogramScale):
        raise TypeError("scale must be a HistogramScale or None")

    if not isinstance(hist, Histogram):
        raise TypeError("hist must be a Histogram")

    if not hist.isnumeric:
        raise TypeError("hist must contain only numeric bins (without context)")

    if not callable(make_value):
        raise TypeError("make_value must be a callable or None")

    if not isinstance(field_names, (list, tuple)) or len(field_names) != len(hist.bin.shape):
        raise ValueError("field_names must be a list or tuple of the same length "
                        "as the histogram's dimension")

    graph = Graph(scale)

    for i, bin_ in enumerate(hist.bins):
        x = bin_.left if get_coordinate == "left" else bin_.right
        y = make_value(bin_, i)
        graph.add_point(Point(x, *y), *field_names)

    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(f"Instance does not provide interface {iface.getName()}")

    missing_methods = []
    for method in iface.getMethods():
        try:
            candidate_method = getattr(candidate, method.getName())
            if not _validateMethodSignature(method, candidate_method):
                missing_methods.append(method.getName())
        except AttributeError:
            missing_methods.append(method.getName())

    if missing_methods:
        raise zope.interface.Invalid(f"Instance does not define methods {missing_methods}")

    missing_attributes = []
    for attribute in iface.getAttributes():
        try:
            getattr(candidate, attribute)
        except AttributeError:
            missing_attributes.append(attribute)

    if missing_attributes:
        raise zope.interface.Invalid(f"Instance does not define attributes {missing_attributes}")

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    # Making sure the candidate claims that it provides the interface using `iface.providedBy`
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid('Candidate does not provide the interface')

    # Making sure the candidate defines all the necessary methods
    if hasattr(iface, 'methods'):
        for method in iface.methods:
            try:
                method_fn = getattr(candidate, method)
            except AttributeError:
                raise zope.interface.Invalid(f'Candidate does not define the method {method}')
            else:
                if not callable(method_fn):
                    raise zope.interface.Invalid(f'Method {method} is not callable')
                signature = inspect.signature(method_fn)
                if not signature.update(**iface.signatures[method]):
                    raise zope.interface.Invalid(f'Method {method} has an invalid signature')

    # Making sure the methods have the correct signature (to the extent possible)
    if hasattr(iface, 'signatures'):
        for method, method_sig in iface.signatures.items():
            try:
                method_fn = getattr(candidate, method)
            except AttributeError:
                raise zope.interface.Invalid(f'Candidate does not define the method {method}')
            else:
                signature = inspect.signature(method_fn)
                if not signature.update(**method_sig):
                    raise zope.interface.Invalid(f'Method {method} has an invalid signature')

    # Making sure the candidate defines all the necessary attributes
    if hasattr(iface, 'attributes'):
        for attr in iface.attributes:
            if not hasattr(candidate, attr):
                raise zope.interface.Invalid(f'Candidate does not define the attribute {attr}')

    # If everything passed, return True
    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise Invalid("Candidate does not provide the interface")

    for name, descriptor in iface.descriptors.items():
        try:
            method = getattr(candidate, name)
        except AttributeError:
            raise Invalid("Candidate does not define method '{}'".format(name))

        if not inspect.ismethod(method) and not inspect.isfunction(method):
            raise Invalid("Method '{}' is not a method or function".format(name))

        if descriptor.positional > 0 and len(inspect.signature(method).parameters) < descriptor.positional:
            raise Invalid("Method '{}' has fewer positional parameters than required".format(name))

        if descriptor.optional > 0 and len(inspect.signature(method).parameters) < descriptor.positional + descriptor.optional:
            raise Invalid("Method '{}' has fewer than the expected number of optional parameters".format(name))

    for name, attr in iface.attributes.items():
        try:
            value = getattr(candidate, name)
        except AttributeError:
            raise Invalid("Candidate does not define attribute '{}'".format(name))

        if not inspect.isclass(value):
            raise Invalid("Attribute '{}' is not a class".format(name))

        if not issubclass(value, attr.interface):
            raise Invalid("Attribute '{}' does not implement interface '{}'".format(name, attr.interface.__name__))

    return True

def verifyObject(iface, candidate, tentative=False):
    # Step 1: Check that the candidate claims to provide the interface
    if not tentative and not iface.providedBy(candidate):
        raise zope.interface.Invalid(
            "The candidate object does not claim to provide the interface {!r}".format(iface)
        )

    # Step 2: Check that the candidate defines all the necessary methods
    missing_methods = []
    for name, signature in iface.namesAndSignatures():
        method = getattr(candidate, name, None)
        if method is None:
            missing_methods.append(name)
        elif signature != inspect.signature(method):
            raise zope.interface.Invalid(
                "The method {!r} does not have the correct signature for interface {!r}".format(
                    name, iface
                )
            )

    if missing_methods:
        raise zope.interface.Invalid(
            "The candidate object does not define the following methods: {}".format(
                ", ".join(missing_methods)
            )
        )

    # Step 3: Check that the candidate defines all the necessary attributes
    missing_attributes = []
    for name, _ in iface.namesAndSignatures():
        if name not in candidate.__dict__:
            missing_attributes.append(name)

    if missing_attributes:
        raise zope.interface.Invalid(
            "The candidate object does not define the following attributes: {}".format(
                ", ".join(missing_attributes)
            )
        )

    return True

def verifyObject(iface, candidate, tentative=False):
    from zope.interface import implementedBy
    from zope.interface import providedBy
    from zope.interface import Invalid

    if not tentative and not implementedBy(iface).providedBy(candidate):
        raise Invalid("The candidate does not implement the interface.")

    missing_methods = []
    for method in iface:
        if not hasattr(candidate, method):
            missing_methods.append(method)
        else:
            candidate_method = getattr(candidate, method)
            if not callable(candidate_method):
                raise Invalid("Method '{}' is not callable.".format(method))
            if not hasattr(candidate_method, "__call__"):
                raise Invalid("Method '{}' does not have a __call__ method.".format(method))

    if missing_methods:
        error = "Candidate is missing the following methods: {}\n".format(
            ", ".join(missing_methods))
        raise Invalid(error)

    missing_attributes = []
    for name, value in iface.namesAndDescriptions():
        if not hasattr(candidate, name):
            missing_attributes.append(name)

    if missing_attributes:
        error = "Candidate is missing the following attributes: {}\n".format(
            ", ".join(missing_attributes))
        raise Invalid(error)

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check if the candidate is a class
    if not inspect.isclass(candidate):
        return False

    # Check if the candidate has the required interface
    for name, value in iface.__annotations__.items():
        if not hasattr(candidate, name):
            return False
        if not isinstance(getattr(candidate, name), value):
            return False

    # If we're being tentative, only check that the candidate has the interface
    # defined by iface, but don't check that it provides valid implementation
    # details like function signatures or attribute types.
    if tentative:
        return True

    # Check that the candidate provides a valid implementation of the interface
    # by checking that it has the same function signatures and attribute types
    # as the interface.
    for name, value in iface.__annotations__.items():
        if not hasattr(candidate, name):
            return False
        if not isinstance(getattr(candidate, name), value):
            return False

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check if the candidate is a subclass of the interface
    if issubclass(candidate, iface):
        return True

    # Check if the candidate has the right methods and attributes
    for method in iface.__abstractmethods__:
        if not hasattr(candidate, method):
            return False
        if not callable(getattr(candidate, method)):
            return False
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclasses = []
    for base in bases:
