    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. Then check if this is a legacy payload.
    """

    for request_type in [PublicRequestType, PrivateRequestType]:
        try:
            typed_request = request_type.parse(request)
            return typed_request
        except ValueError:
            pass

    try:
        typed_request = LegacyRequestType.parse(request)
        return typed_request
    except ValueError:
        pass

    return None

