def find_tags(text, replacer=None):
    tags = set()
    code_block = False
    for word in text.split():
        if word == "```":
            code_block = not code_block
        elif not code_block and word.startswith("#"):
            tags.add(word)
            if replacer:
                word = replacer(word)
    return tags, text.replace(word, replacer(word))

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    is_code_block = False
    for word in text.split():
        if word == "```":
            is_code_block = not is_code_block
        if not is_code_block and word.startswith("#"):
            tag = word[1:]
            tags.add(tag)
            if replacer is not None:
                text = text.replace(word, replacer(tag))
    return (tags, text)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    modified_text = ""
    in_code_block = False

    for word in text.split():
        if word.startswith("<"):
            in_code_block = True
        if word.endswith(">") and in_code_block:
            in_code_block = False
        if not in_code_block and word.isalpha() and word.islower():
            tags.add(word)
            if replacer:
                word = replacer(word)
        modified_text += word + " "

    return tags, modified_text.strip()

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    start_index = 0
    while start_index < len(text):
        start_index = text.find("weak", start_index)
        if start_index == -1:
            break
        end_index = text.find(" ", start_index)
        if end_index == -1:
            end_index = len(text)
        tag = text[start_index:end_index]
        tags.add(tag)
        if replacer is not None:
            text = text.replace(tag, replacer(tag))
    return tags, text

def find_tags(text, replacer=None):
    """
    Find tags in text and return a set of tags and the original or replaced text.
    """
    tags = set()
    for word in text.split():
        if word.startswith("#"):
            tags.add(word[1:])
            if replacer:
                text = text.replace(word, replacer(word[1:]))
    return tags, text

