    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    if not public_key:
        raise ValueError("Public key is required for signature verification")
    if not doc:
        raise ValueError("Document to be verified is required")
    if not signature:
        raise ValueError("Signature to be verified is required")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from typing import Dict

    try:
        # Try parsing as JSON format
        json_data = json.loads(document)
        return json_data
    except json.JSONDecodeError:
        # If JSON parsing fails, assume it's in XRD format
        xrd_data = {}
        for line in document.splitlines():
            if line.startswith("rel="):
                key, val = line.split("=", 1)
                xrd_data[key.strip()] = val.strip()
        return xrd_data

def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        pass

    # Parse XRD format
    xrd = xrdlib.parse(document)

    # Extract relevant information
    subject = xrd.subject.uri
    aliases = [link.href for link in xrd.links if link.rel == "http://schemas.google.com/buzz/2011/auth/clientid"]
    properties = {link.prop: link.href for link in xrd.links if link.prop is not None and link.prop.uri in AUTHORIZATION_PROP_URIS}

    return {
        "subject": subject,
        "aliases": aliases,
        "properties": properties,
    }

