def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        xml_root = ET.fromstring(document)
        result = {}
        for elem in xml_root.iter():
            if elem.tag == 'XRD':
                result['subject'] = elem.find('Subject').text
                result['aliases'] = []
                for alias_elem in elem.findall('Alias'):
                    result['aliases'].append(alias_elem.text)
                result['links'] = []
                for link_elem in elem.findall('Link'):
                    link = {
                        'href': link_elem.get('href'),
                        'rel': link_elem.get('rel'),
                        'type': link_elem.get('type'),
                    }
                    result['links'].append(link)
                return result
        return None
    except Exception as e:
        try:
            json_doc = json.loads(document)
            if json_doc.get('subject'):
                return {
                    'subject': json_doc.get('subject'),
                    'aliases': json_doc.get('aliases'),
                    'links': json_doc.get('links'),
                }
        except Exception as e:
            return None

def parse_diaspora_webfinger(document: str) -> Dict:
    # Check if the document is in JSON format (new)
    if document.startswith('{'):
        try:
            # Parse JSON document
            data = json.loads(document)
            # Extract relevant entries
            alias = data['links']['alias']
            links = data['links']['links']
            preferred_username = data['preferred_username']
            return {
                'alias': alias,
                'links': links,
                'preferred_username': preferred_username
            }
        except (JSONDecodeError, KeyError) as e:
            # Handle invalid JSON or missing entries
            raise ValueError('Invalid Diaspora webfinger JSON document') from e
    # Otherwise, assume the document is in XRD format (old)
    else:
        try:
            # Parse XRD document
            data = xrd.parse_xrd_document(document)
            # Extract relevant entries
            alias = data.alias
            links = data.links
            preferred_username = data.preferred_username
            return {
                'alias': alias,
                'links': links,
                'preferred_username': preferred_username
            }
        except XRDParseError as e:
            # Handle invalid XRD or missing entries
            raise ValueError('Invalid Diaspora webfinger XRD document') from e

