def retrieve_and_parse_diaspora_webfinger(handle):
    import requests

    response = requests.get('https://diasporahub.org/.well-known/webfinger', params={'resource': handle})
    response.raise_for_status()
    data = response.json()
    if 'links' not in data or len(data['links']) == 0:
        return {}
    link = data['links'][0]
    if 'properties' not in link or 'http://openid.net/specs/connect/1.0/issuer' not in link['properties']:
        return {}
    issuer = link['properties']['http://openid.net/specs/connect/1.0/issuer']
    idp_uri = issuer + '/openid/connect/'
    webfinger = {
        'issuer': issuer,
        'idp_uri': idp_uri,
    }
    return webfinger

