def validate_from_content(cls, spec_content=None):
    """
    Validates that spec (YAML) content has all required fields.

    :param spec_content: The content of the spec file.
    :raise IRValidatorException: When mandatory data is missing in the spec file.
    :return: A dictionary with the data loaded from a spec (YAML) file.
    """
    try:
        spec_dict = yaml.safe_load(spec_content)
    except yaml.YAMLException as e:
        raise IRValidatorException("Spec content is not valid YAML") from e

    required_fields = ["apiVersion", "kind", "metadata", "spec"]

    for field in required_fields:
        if field not in spec_dict:
            raise IRValidatorException(f"Spec content is missing required field: {field}")

    return spec_dict

