def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Args:
        parser_dict (dict): A dictionary containing the parsed spec file data.

    Returns:
        dict: A dictionary containing the resolved include directive data.
    """
    resolved_dict = {}
    for key, value in parser_dict.items():
        if isinstance(value, dict) and "$include" in value:
            include_path = value["$include"]
            resolved_dict[key] = self._resolve_include(include_path)
