    return resolved_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary containing the resolved arguments' values.
    """
    # Get the arguments from the spec
    spec_args = self.spec.arguments

    # Initialize an empty dictionary to store the resolved arguments
    resolved_args = {}

    # Iterate over the arguments and resolve their values
    for arg_name, arg_value in spec_args.items():
        # If the argument has a default value, use it
        if arg_value is not None:
            resolved_args[arg_name] = arg_value
        # Otherwise, try to get the value from the input data
        else:
            try:
                resolved_args[arg_name] = self.input_data[arg_name]
            except KeyError:
                raise MissingArgumentError(
                    f"Argument '{arg_name}' is required but was not provided."
                ) from None

    return resolved_args

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.
    """
    # Get the default values from the spec
    default_values = {
        argument: value
        for argument, value in self.spec.arguments.items()
        if value is not None
    }

    # Get the overridden values from the config
    overridden_values = {
        argument: value
        for argument, value in self.config.items()
        if argument in self.spec.arguments and value is not None
    }

    # Combine the default and overridden values
    combined_values = {**default_values, **overridden_values}

    return combined_values

