        raise ValueError(f"Invalid option name '{argument_name}' for command '{command_name}''")
    return option_spec

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Try to find the option in the command's arguments
    for argument in self.commands[command_name].arguments:
        if argument.name == argument_name:
            return argument

    # If the option is not found, try to find it in the command's options
    for option in self.commands[command_name].options:
        if option.name == argument_name:
            return option

    # If the option is not found, raise an error
    raise ValueError(f"Option '{argument_name}' not found in command '{command_name}'")

