def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Check if the number of arguments is valid
    if len(args) < 2:
        raise ValueError("Invalid number of arguments. Expected at least 2, received {}".format(len(args)))

    # Check if the first argument is a valid minimum value
    try:
        min_value = float(args[0])
    except ValueError:
        raise ValueError("Invalid minimum value: {}".format(args[0]))

    # Check if the second argument is a valid maximum value
    try:
        max_value = float(args[1])
    except ValueError:
        raise ValueError("Invalid maximum value: {}".format(args[1]))

    # Check if the minimum value is less than or equal to the maximum value
    if min_value > max_value:
        raise ValueError("Minimum value must be less than or equal to maximum value")

    # Check if the remaining arguments are valid values between the minimum and maximum values
    for arg in args[2:]:
        try:
            value = float(arg)
            if value < min_value or value > max_value:
                raise ValueError("Value {} is not between minimum value {} and maximum value {}".format(value, min_value, max_value))
        except ValueError:
            raise ValueError("Invalid value: {}".format(arg))

