def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """
    command = ['ansible-playbook']
    if verbose:
        command.append(f'-{verbose}')
    if extra_vars:
        command.append(f"-e '{json.dumps(extra_vars)}'")
    if ansible_args:
        for arg in ansible_args:
            command.append(f"{arg} '{ansible_args[arg]}'")
    command.append(playbook_path)
    try:
        subprocess.run(command, cwd=ir_workspace.workspace_dir)
    except FileNotFoundError:
        raise InfraredCliError(f"Playbook not found at {playbook_path}")

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
        workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    """
    from subprocess import run, PIPE

    command = ['ansible-playbook', playbook_path]

    if verbose:
        command.append('-v')

    if extra_vars:
        for k, v in extra_vars.items():
            command.append(f'--extra-vars="{k}={v}"')

    if ansible_args:
        for k, v in ansible_args.items():
            command.append(f'--{k}={v}')

    result = run(command, check=True, stdout=PIPE, stderr=PIPE)

    return result.stdout.decode('utf-8')

def _convert_non_cli_args(self, parser_name, values_dict):
    # Get the command line argument parser for the given command
    parser = self.parsers[parser_name]

    # Iterate over the arguments and cast them to the correct type
    for arg_name, arg_value in values_dict.items():
        if arg_name in parser.arguments:
            arg_type = parser.arguments[arg_name].type
            if arg_type and arg_type.lower() == "bool":
                values_dict[arg_name] = self._convert_boolean(arg_value)
            elif arg_type and arg_type.lower() == "int":
                values_dict[arg_name] = self._convert_integer(arg_value)
            elif arg_type and arg_type.lower() == "float":
                values_dict[arg_name] = self._convert_float(arg_value)

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    parser = self._cmd_parser[parser_name]
    for name, value in values_dict.items():
        arg_spec = parser._get_argument(name)
        if not arg_spec:
            raise ValueError(f"Invalid argument {name} for command {parser_name}")
        if value is not None:
            values_dict[name] = arg_spec.type(value)

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Cast the values to the correct types
    for key, value in values_dict.items():
        if value.isdigit():
            values_dict[key] = int(value)
        elif value.replace('.', '', 1).isdigit():
            values_dict[key] = float(value)
        elif value == 'true' or value == 'false':
            values_dict[key] = value == 'true'
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

