        values_dict[name] = value

def _convert_non_cli_args(self, parser_name, values_dict):
    # Iterate over the values in the values_dict
    for key, value in values_dict.items():
        # Check if the value is a string
        if isinstance(value, str):
            # If the value is a string, try to convert it to the correct type
            # based on the command name
            if parser_name == "main":
                values_dict[key] = _convert_main_non_cli_arg(key, value)
            elif parser_name == "virsh":
                values_dict[key] = _convert_virsh_non_cli_arg(key, value)
            elif parser_name == "ospd":
                values_dict[key] = _convert_ospd_non_cli_arg(key, value)
            else:
                raise ValueError(f"Unknown parser name: {parser_name}")

    # Return the updated values_dict
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = get_plugin_spec(plugin_dir)
    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                flatten_dict[f"{key}_{sub_key}"] = sub_value
        else:
            flatten_dict[key] = value
    return flatten_dict

